Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
ipvs: clear the svc scheduler ptr early on edit

ip_vs_edit_service() while unbinding the old scheduler clears
the svc->scheduler ptr after the scheduler module initiates
RCU callbacks. This can cause packets to use the old
scheduler at the time when svc->sched_data is already freed
after RCU grace period.

Fix it by clearing the ptr early in ip_vs_unbind_scheduler(),
before the done_service method schedules any RCU callbacks.

Also, if the new scheduler fails to initialize when replacing
the old scheduler, try to restore the old scheduler while still
returning the error code.

Link: https://sashiko.dev/#/patchset/20260519015506.634185-1-rosenp%40gmail.com
Fixes: 05f00505a89a ("ipvs: fix crash if scheduler is changed")
Signed-off-by: Julian Anastasov <ja@ssi.bg>
Signed-off-by: Florian Westphal <fw@strlen.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
In the `ip_vs_edit_service()` function within `ip_vs_ctl.c`, the old scheduler pointer (`svc->scheduler`) was cleared **after** invoking the scheduler's `done_service` method. That method can schedule RCU callbacks that free the scheduler's private data (`sched_data`). The pointer was cleared later with `RCU_INIT_POINTER(svc->scheduler, NULL)`, leaving a window where incoming packets might still see the old scheduler pointer and access already freed memory, causing a use-after-free race condition.

Here is the patch:
  */
 static int
 ip_vs_add_service(struct netns_ipvs *ipvs, struct ip_vs_service_user_kern *u,
 		  struct ip_vs_service **svc_p)
 {
 	struct ip_vs_scheduler *sched = NULL;
 	struct ip_vs_rht *tc_new = NULL;
 	struct ip_vs_rht *t, *t_new = NULL;
 	int af_id = ip_vs_af_index(u->af);
 	struct ip_vs_service *svc = NULL;
 	struct ip_vs_pe *pe = NULL;
 	int ret_hooks = -1;
 	int ret = 0;
 	bool grow;

 	/* increase the module use count */
 	if (!ip_vs_use_count_inc())
 		return -ENOPROTOOPT;

 	/* Lookup the scheduler by 'u->sched_name' */
 	if (strcmp(u->sched_name, "none")) {
 		sched = ip_vs_scheduler_get(u->sched_name);
 		if (!sched) {
 			pr_info("Scheduler module ip_vs_%s not found\n",
 				u->sched_name);
 			ret = -ENOENT;
 			goto out_err;
 		}
 	}

 	if (u->pe_name && *u->pe_name) {
 		pe = ip_vs_pe_getbyname(u->pe_name);
 		if (pe == NULL) {
 			pr_info("persistence engine module ip_vs_pe_%s "
 				"not found\n", u->pe_name);
 			ret = -ENOENT;
 			goto out_err;
 		}
 	}

 #ifdef CONFIG_IP_VS_IPV6
 	if (u->af == AF_INET6) {
 		__u32 plen = (__force __u32) u->netmask;

 		if (plen < 1 || plen > 128) {
 			ret = -EINVAL;
 			goto out_err;
 		}

 		ret = nf_defrag_ipv6_enable(ipvs->net);
 		if (ret)
 			goto out_err;
 	}
 #endif

 	/* The old table can be freed, protect it with RCU */
 	rcu_read_lock();
 	t = rcu_dereference(ipvs->svc_table);
 	if (!t) {
 		int lfactor = sysctl_svc_lfactor(ipvs);
 		int new_size = ip_vs_svc_desired_size(ipvs, NULL, lfactor);

 		rcu_read_unlock();
 		t_new = ip_vs_svc_table_alloc(ipvs, new_size, lfactor);
 		if (!t_new) {
 			ret = -ENOMEM;
 			goto out_err;
 		}
 		grow = false;
 	} else {
 		/* Even the currently attached new table may need to grow */
 		t = rcu_dereference(t->new_tbl);
 		grow = ip_vs_get_num_services(ipvs) + 1 > t->u_thresh;
 		rcu_read_unlock();
 	}

 	if (!rcu_dereference_protected(ipvs->conn_tab, 1)) {
 		int lfactor = sysctl_conn_lfactor(ipvs);
 		int new_size = ip_vs_conn_desired_size(ipvs, NULL, lfactor);

 		tc_new = ip_vs_conn_tab_alloc(ipvs, new_size, lfactor);
 		if (!tc_new) {
 			ret = -ENOMEM;
 			goto out_err;
 		}
 	}

 	if (!atomic_read(&ipvs->num_services[af_id])) {
 		ret = ip_vs_register_hooks(ipvs, u->af);
 		if (ret < 0)
 			goto out_err;
 		ret_hooks = ret;
 	}

 	svc = kzalloc_obj(struct ip_vs_service);
 	if (svc == NULL) {
 		IP_VS_DBG(1, "%s(): no memory\n", __func__);
 		ret = -ENOMEM;
 		goto out_err;
 	}
 	ret = ip_vs_stats_init_alloc(&svc->stats);
 	if (ret < 0)
 		goto out_err;

 	/* I'm the first user of the service */
 	atomic_set(&svc->refcnt, 0);

 	svc->af = u->af;
 	svc->protocol = u->protocol;
 	ip_vs_addr_copy(svc->af, &svc->addr, &u->addr);
 	svc->port = u->port;
 	svc->fwmark = u->fwmark;
 	svc->flags = u->flags & ~IP_VS_SVC_F_HASHED;
 	svc->timeout = u->timeout * HZ;
 	svc->netmask = u->netmask;
 	svc->ipvs = ipvs;

 	INIT_LIST_HEAD(&svc->destinations);
 	spin_lock_init(&svc->sched_lock);

 	/* Bind the scheduler */
 	if (sched) {
 		ret = ip_vs_bind_scheduler(svc, sched);
 		if (ret)
 			goto out_err;
 	}

 	ret = ip_vs_start_estimator(ipvs, &svc->stats);
 	if (ret < 0)
 		goto out_err;

 	if (t_new) {
 		/* Add table for first time */
 		clear_bit(IP_VS_WORK_SVC_NORESIZE, &ipvs->work_flags);
 		rcu_assign_pointer(ipvs->svc_table, t_new);
 		t_new = NULL;
 	}
 	if (tc_new) {
 		rcu_assign_pointer(ipvs->conn_tab, tc_new);
 		tc_new = NULL;
 	}

 	/* Update the virtual service counters */
 	if (svc->port == FTPPORT)
 		atomic_inc(&ipvs->ftpsvc_counter[af_id]);
 	else if (!svc->port && !svc->fwmark)
 		atomic_inc(&ipvs->nullsvc_counter[af_id]);
 	if (pe && pe->conn_out)
 		atomic_inc(&ipvs->conn_out_counter[af_id]);

 	/* Bind the ct retriever */
 	RCU_INIT_POINTER(svc->pe, pe);
 	pe = NULL;

